	function validUid(uid) {
		return /^[1-9]\d*$/.test(String(uid)) && Number.isSafeInteger(Number(uid));
	}

	function profileFolder() {
		return path.resolve(nconf.get('upload_path'), 'profile');
	}

	function isProfileImageFilename(filename, uid, type) {
		if (!validUid(uid)) {
			return false;
		}
		const parsed = path.parse(filename);
		const extensions = User.getAllowedProfileImageExtensions();
		if (!extensions.includes(parsed.ext.slice(1).toLowerCase())) {
			return false;
		}
		const prefix = `${uid}-profile${type}`;
		return parsed.name === prefix ||
			(parsed.name.startsWith(prefix) && /^-\d+$/.test(parsed.name.slice(prefix.length)));
	}

	function getLocalProfilePath(url, uid, type) {
		const prefix = `${nconf.get('relative_path') || ''}/assets/uploads/profile/`;
		if (typeof url !== 'string' || !url.startsWith(prefix)) {
			return false;
		}
		const filename = url.slice(prefix.length);
		if (!filename || path.basename(filename) !== filename || !isProfileImageFilename(filename, uid, type)) {
			return false;
		}
		const folder = profileFolder();
		const localPath = path.resolve(folder, filename);
		return path.dirname(localPath) === folder ? localPath : false;
	}

	async function getProfileImagePaths(uid, type) {
		if (!validUid(uid)) {
			throw new Error('[[error:invalid-uid]]');
		}
		let filenames;
		try {
			filenames = await fs.promises.readdir(profileFolder());
		} catch (err) {
			if (err.code === 'ENOENT') {
				return [];
			}
			throw err;
		}
		return filenames.filter(filename => isProfileImageFilename(filename, uid, type))
			.map(filename => path.join(profileFolder(), filename));
	}

	async function unlinkProfileImage(localPath) {
		try {
			await fs.promises.unlink(localPath);
		} catch (err) {
			if (err.code !== 'ENOENT') {
				throw err;
			}
		}
	}

	async function getLocalImagePath(uid, type, field) {
		if (!validUid(uid)) {
			return false;
		}
		const url = await User.getUserField(uid, field);
		const currentPath = getLocalProfilePath(url, uid, type);
		if (currentPath && await file.exists(currentPath)) {
			return currentPath;
		}
		const paths = await getProfileImagePaths(uid, type);
		return paths[0] || false;
	}

	User.getLocalCoverPath = async function (uid) {
		return await getLocalImagePath(uid, 'cover', 'cover:url');
	};

	User.getLocalAvatarPath = async function (uid) {
		return await getLocalImagePath(uid, 'avatar', 'uploadedpicture');
	};

	function validateUpload(data, maxSize, allowedTypes) {
		if (!data.imageData) {
			throw new Error('[[error:invalid-data]]');
		}
		const size = image.sizeFromBase64(data.imageData);
		if (size > maxSize * 1024) {
			throw new Error(`[[error:file-too-big, ${maxSize}]]`);
		}

		const type = image.mimeFromBase64(data.imageData);
		if (!type || !allowedTypes.includes(type)) {
			throw new Error('[[error:invalid-image]]');
		}
	}

	async function convertToPNG(path) {
		const convertToPNG = meta.config['profile:convertProfileImageToPNG'] === 1;
		if (!convertToPNG) {
			return path;
		}
		const newPath = await image.normalise(path);
		await file.delete(path);
		return newPath;
	}

	function generateProfileImageFilename(uid, extension) {
		const convertToPNG = meta.config['profile:convertProfileImageToPNG'] === 1;
		return `${uid}-profileavatar-${Date.now()}${convertToPNG ? '.png' : extension}`;
	}

	User.removeCoverPicture = async function (uid) {
		const paths = await getProfileImagePaths(uid, 'cover');
		await Promise.all(paths.map(unlinkProfileImage));
		await db.deleteObjectFields(`user:${uid}`, ['cover:url', 'cover:position']);
		return { success: true };
	};

	User.removeProfileImage = async function (uid) {
		if (!validUid(uid)) {
			throw new Error('[[error:invalid-uid]]');
		}
		const userData = await User.getUserFields(uid, ['uploadedpicture', 'picture']);
		const paths = await getProfileImagePaths(uid, 'avatar');
		await Promise.all(paths.map(unlinkProfileImage));
		await User.setUserFields(uid, {
			uploadedpicture: '',
			picture: userData.picture === userData.uploadedpicture ? '' : userData.picture,
		});
		return userData;
	};
};

